import { useState } from "react";
import { useDispatch, useSelector } from "react-redux";
import { registerUser } from "../Features/UserSlice";
import { useNavigate, Link } from "react-router-dom";
import { userSchemaValidation } from "../Validation/UserValidation"; // ✅ validation schema
import * as yup from "yup";
import { useForm } from "react-hook-form";
import { yupResolver } from "@hookform/resolvers/yup";
import {
  Button,
  Container,
  Row,
  Col,
  Form,
  Input,
  Label,
  FormGroup,
} from "reactstrap";
import "../Styles/UserRegister.css";
import registerImg from "../Images/login-side.png";

const MAJORS = [
  "",
  "Information Technology",
  "Business Administration",
  "Engineering",
  "Mass Communication",
];

const UserRegister = () => {
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const { isLoading } = useSelector((state) => state.users);

  // Local states
  const [name, setname] = useState("");
  const [email, setemail] = useState("");
  const [password, setpassword] = useState("");
  const [major, setmajor] = useState("");
  const [age, setage] = useState("");

  // Form validation hook
  const {
    register,
    handleSubmit,
    formState: { errors },
  } = useForm({
    resolver: yupResolver(userSchemaValidation),
  });

  // Handle form submit
  const onSubmit = (data) => {
    try {
      const userData = {
        name: data.name,
        email: data.email,
        password: data.password,
        major: data.major,
        age: data.age,
      };
      dispatch(registerUser(userData));
      alert("Validation successful! Student registered.");
      navigate("/user-profile");
    } catch (error) {
      console.log("Registration error:", error);
      alert("Registration failed!");
    }
  };

  return (
    <div className="register-page">
      <div className="register-container">
        {/* Left side - form */}
        <div className="register-form">
          <h1 className="reg-title">
            Create your <span className="accent">account</span>
          </h1>
          <p className="reg-sub">Please fill in your details to continue</p>

          {/* Role switch */}
          <div className="role-switch">
            <Link to="/user-register" className="role-btn active">
              Student
            </Link>
            <Link to="/company-register" className="role-btn">
              Company
            </Link>
          </div>

          {/* Registration Form */}
          <Container>
            <Form onSubmit={handleSubmit(onSubmit)}>
              <Row>
                <Col md={12}>
                  <Label>Full Name</Label>
                  <Input
                    type="text"
                    name="name"
                    placeholder="Your name"
                    {...register("name", {
                      value: name,
                      onChange: (e) => setname(e.target.value),
                    })}
                  />
                  <p className="error">{errors.name?.message}</p>
                </Col>
              </Row>

              <Row>
                <Col md={12}>
                  <Label>Email</Label>
                  <Input
                    type="email"
                    name="email"
                    placeholder="you@example.com"
                    {...register("email", {
                      value: email,
                      onChange: (e) => setemail(e.target.value),
                    })}
                  />
                  <p className="error">{errors.email?.message}</p>
                </Col>
              </Row>

              <Row>
                <Col md={12}>
                  <Label>Password</Label>
                  <Input
                    type="password"
                    name="password"
                    placeholder="********"
                    {...register("password", {
                      value: password,
                      onChange: (e) => setpassword(e.target.value),
                    })}
                  />
                  <p className="error">{errors.password?.message}</p>
                </Col>
              </Row>

              <Row>
                <Col md={6}>
                  <Label>Major</Label>
                  <Input
                    type="select"
                    name="major"
                    {...register("major", {
                      value: major,
                      onChange: (e) => setmajor(e.target.value),
                    })}
                  >
                    {MAJORS.map((m, i) => (
                      <option key={i} value={m}>
                        {m === "" ? "Select your major" : m}
                      </option>
                    ))}
                  </Input>
                  <p className="error">{errors.major?.message}</p>
                </Col>

                <Col md={6}>
                  <Label>Age</Label>
                  <Input
                    type="number"
                    min="19"
                    max="25"
                    name="age"
                    {...register("age", {
                      value: age,
                      onChange: (e) => setage(e.target.value),
                    })}
                  />
                  <p className="error">{errors.age?.message}</p>
                </Col>
              </Row>

              <Row>
                <Col md={12}>
                  <Button
                    color="primary"
                    type="submit"
                    className="reg-btn"
                    disabled={isLoading}
                  >
                    {isLoading ? "Registering..." : "Sign up"}
                  </Button>
                </Col>
              </Row>

              <p className="login-text">
                Already have an account?{" "}
                <Link to="/login" className="login-link">
                  Log in now!
                </Link>
              </p>
            </Form>
          </Container>
        </div>

        {/* Right side - image */}
        <div className="register-image">
          <img src={registerImg} alt="Registration illustration" />
        </div>
      </div>
    </div>
  );
};

export default UserRegister;
